BEGIN;
ALTER TABLE public.redirects DROP CONSTRAINT redirects_pending_tenant_fence;
ALTER TABLE public.redirect_events DROP CONSTRAINT redirect_events_pending_tenant_fence;
ALTER TABLE public.redirect_link_policies DROP CONSTRAINT redirect_link_policies_pending_tenant_fence;
ALTER TABLE public.redirect_native_apps DROP CONSTRAINT redirect_native_apps_pending_tenant_fence;
ALTER TABLE public.redirect_native_handoff_receipts DROP CONSTRAINT redirect_native_handoff_receipts_pending_tenant_fence;
ALTER TABLE public.redirect_domains DROP CONSTRAINT redirect_domains_pending_tenant_fence;
ALTER TABLE public.redirect_qr_assets DROP CONSTRAINT redirect_qr_assets_pending_tenant_fence;
ALTER TABLE public.redirect_password_branding DROP CONSTRAINT redirect_password_branding_pending_tenant_fence;
ALTER TABLE public.redirect_password_attempts DROP CONSTRAINT redirect_password_attempts_pending_tenant_fence;
ALTER TABLE public.redirect_qr_image_links DROP CONSTRAINT redirect_qr_image_links_pending_tenant_fence;
ALTER TABLE public.redirect_qr_image_creation_log DROP CONSTRAINT redirect_qr_image_creation_log_pending_tenant_fence;
SET LOCAL ROLE service_role;
DO $$
DECLARE legacy uuid:='58aa4340-8f21-4b7f-9a10-90be2da89c01';other uuid:=gen_random_uuid();actor uuid:=gen_random_uuid();foreign_link uuid:=gen_random_uuid();own_link uuid;foreign_app uuid:=gen_random_uuid();own_app uuid;foreign_domain uuid:=gen_random_uuid();foreign_click uuid:=gen_random_uuid();expired_click uuid:=gen_random_uuid();foreign_asset uuid:=gen_random_uuid();foreign_orphan_asset uuid:=gen_random_uuid();own_asset uuid;foreign_lease uuid:=gen_random_uuid();foreign_image uuid:=gen_random_uuid();own_image uuid:=gen_random_uuid();app_version uuid;foreign_fp text;op text;row public.redirects;golden public.redirects;result jsonb;snapshot jsonb;own_receipt jsonb;old_count integer;
BEGIN
 INSERT INTO auth.users(id) VALUES(actor);INSERT INTO public.user_roles VALUES(actor,'admin');
 INSERT INTO public.redirect_workspaces(id,name,slug) VALUES(other,'Native asset fixture','native-asset-fixture');
 INSERT INTO redirect_internal.workspace_owners(workspace_id,user_id) VALUES(other,actor);
 INSERT INTO public.redirect_domains(id,workspace_id,hostname,created_by) VALUES(foreign_domain,other,'foreign-native.example.com',actor);
 INSERT INTO public.redirects(id,workspace_id,type,slug,target) VALUES(foreign_link,other,'SHORT','foreign-native-scope','https://example.org/foreign-native');
 INSERT INTO public.redirect_link_policies(workspace_id,redirect_id,policy) VALUES(other,foreign_link,'{"track_conversions":true}');
 INSERT INTO public.redirect_native_apps(id,workspace_id,domain_id,label,platform,app_id,app_clip_id,public_name,store_id,app_group_id,handoff_enabled,enabled,created_by,paths) VALUES(foreign_app,other,foreign_domain,'Foreign private app','ios','ABCDE12345.org.qg.ForeignScope','ABCDE12345.org.qg.ForeignScope.Clip','Foreign app','12345','group.org.qg.ForeignScope',true,true,actor,ARRAY['/go/*']) RETURNING revision INTO app_version;
 INSERT INTO public.redirect_events(workspace_id,redirect_id,click_id,path,query,destination_url,visitor) VALUES(other,foreign_link,foreign_click,'/go/foreign-native-scope','foreign-private-query','https://example.org/foreign-native','{"domain":"queer.guide"}'),(other,foreign_link,expired_click,'/go/foreign-native-scope','','https://example.org/foreign-native','{"domain":"queer.guide"}');
 SELECT * INTO row FROM public.redirects WHERE id=foreign_link;foreign_fp:=public.redirect_resolution_fingerprint(row,'{"track_conversions":true}',NULL);
 INSERT INTO public.redirect_native_handoff_receipts(workspace_id,token_hash,redirect_id,click_id,app_binding,app_revision,routing_fingerprint,hostname,path,expires_at) VALUES(other,repeat('a',64),foreign_link,foreign_click,foreign_app,app_version,foreign_fp,'queer.guide','/go/foreign-native-scope',clock_timestamp()+interval '1 hour');
 INSERT INTO public.redirect_native_handoff_receipts(workspace_id,token_hash,redirect_id,click_id,app_binding,app_revision,routing_fingerprint,hostname,path,created_at,expires_at) VALUES(other,repeat('b',64),foreign_link,expired_click,foreign_app,app_version,foreign_fp,'queer.guide','/go/foreign-native-scope',now()-interval '2 days',now()-interval '1 day');
 INSERT INTO public.redirect_qr_assets(id,workspace_id,target_scope,password_link_id,requested_by,mime,bytes,width,height,sha256,state) VALUES(foreign_asset,other,'password:'||foreign_link,foreign_link,actor,'image/png',8,1,1,repeat('a',64),'active');
 INSERT INTO public.redirect_password_branding(workspace_id,link_id,brand_name,logo_asset_id) VALUES(other,foreign_link,'Foreign private brand',foreign_asset);
 INSERT INTO public.redirect_qr_assets(id,workspace_id,target_scope,requested_by,mime,bytes,width,height,sha256,state,lease,lease_until,next_cleanup_at) VALUES(foreign_orphan_asset,other,'workspace',actor,'image/png',8,1,1,repeat('b',64),'deleting',foreign_lease,now()+interval '1 hour',now()-interval '1 day');
 INSERT INTO public.redirect_password_attempts(workspace_id,redirect_id,client_hash,window_started_at,attempts) VALUES(other,foreign_link,repeat('c',64),now()-interval '3 days',3);
 INSERT INTO public.redirect_qr_image_links(id,workspace_id,token_hash,creator_user_id,principal_key,encoded_url,created_at,expires_at,revoked_at) VALUES(foreign_image,other,repeat('c',64),actor,'owner:'||actor,'https://example.org/foreign-qr',now()-interval '200 days',now()-interval '100 days',now()-interval '100 days');
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-workspace',legacy,'x-qg-redirect-session-actor',actor)::text,true);
 INSERT INTO public.redirects(type,slug,target) VALUES('SHORT','own-native-scope','https://example.org/own-native') RETURNING id INTO own_link;
 INSERT INTO public.redirect_link_policies(redirect_id,policy) VALUES(own_link,'{"track_conversions":true}');
 result:=public.redirect_native_app_admin(actor,'create',p_values=>'{"label":"Local private app","platform":"ios","appId":"ABCDE12345.org.qg.LocalScope","appClipId":"ABCDE12345.org.qg.LocalScope.Clip","publicName":"Local app","storeId":"23456","appGroupId":"group.org.qg.LocalScope","handoffEnabled":true,"enabled":true}');own_app:=(result->>'id')::uuid;
 SELECT jsonb_build_object('links',(SELECT jsonb_agg(to_jsonb(r)) FROM public.redirects r WHERE workspace_id=other),'events',(SELECT jsonb_agg(to_jsonb(e) ORDER BY id) FROM public.redirect_events e WHERE workspace_id=other),'apps',(SELECT jsonb_agg(to_jsonb(a)) FROM public.redirect_native_apps a WHERE workspace_id=other),'receipts',(SELECT jsonb_agg(to_jsonb(h) ORDER BY token_hash) FROM public.redirect_native_handoff_receipts h WHERE workspace_id=other),'assets',(SELECT jsonb_agg(to_jsonb(a) ORDER BY id) FROM public.redirect_qr_assets a WHERE workspace_id=other),'brand',(SELECT jsonb_agg(to_jsonb(b)) FROM public.redirect_password_branding b WHERE workspace_id=other),'attempts',(SELECT jsonb_agg(to_jsonb(a)) FROM public.redirect_password_attempts a WHERE workspace_id=other),'images',(SELECT jsonb_agg(to_jsonb(q)) FROM public.redirect_qr_image_links q WHERE workspace_id=other),'imageLog',(SELECT jsonb_agg(to_jsonb(q)) FROM public.redirect_qr_image_creation_log q WHERE workspace_id=other)) INTO snapshot;
 IF public.redirect_native_app_admin(actor,'list')->>'count'<>'1' THEN RAISE EXCEPTION 'Foreign native app page/count exposed';END IF;
 FOREACH op IN ARRAY ARRAY['update','delete'] LOOP
  BEGIN PERFORM public.redirect_native_app_admin(actor,op,foreign_app,'{"label":"denied"}',app_version);RAISE EXCEPTION 'Foreign app changed/deleted';EXCEPTION WHEN no_data_found THEN NULL;END;
 END LOOP;
 BEGIN PERFORM public.redirect_native_app_admin(actor,'create',p_values=>jsonb_build_object('domainId',foreign_domain,'label','Denied','platform','ios','appId','ABCDE12345.org.qg.Denied'));RAISE EXCEPTION 'Foreign app domain assigned';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 IF public.redirect_native_app_json((SELECT a FROM public.redirect_native_apps a WHERE id=foreign_app)) IS NOT NULL OR public.redirect_password_branding_json(foreign_link) IS NOT NULL THEN RAISE EXCEPTION 'Private native/branding serializer exposed foreign data';END IF;
 BEGIN PERFORM public.redirect_password_branding_resource('get',actor,NULL,foreign_link);RAISE EXCEPTION 'Foreign password branding read';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.reserve_redirect_password_logo(actor,NULL,foreign_link,NULL,'image/png',8,1,1,repeat('d',64));RAISE EXCEPTION 'Foreign branding upload reserved';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.finish_redirect_password_logo(actor,NULL,own_link,foreign_asset);RAISE EXCEPTION 'Foreign asset attached to local branding';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 -- Public reads derive authoritative routing identity even with a foreign header.
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-workspace',other)::text,true);
 result:=public.redirect_native_apps_public('queer.guide');
 IF jsonb_array_length(result)<>1 OR result::text LIKE '%ForeignScope%' THEN RAISE EXCEPTION 'Public association exposed another workspace';END IF;
 result:=public.redirect_native_install_choices('queer.guide','/go/own-native-scope');
 IF jsonb_array_length(result)<>1 OR result::text LIKE '%Foreign%' THEN RAISE EXCEPTION 'Public install chooser exposed foreign app';END IF;
 IF (public.redirect_native_handoff_app(foreign_app,'queer.guide','/go/foreign-native-scope')).id IS NOT NULL OR public.redirect_resolution_snapshot('queer.guide','foreign-native-scope') IS NOT NULL OR public.redirect_native_handoff_context(repeat('a',64),foreign_app,'queer.guide','/go/foreign-native-scope',true) IS NOT NULL OR public.consume_redirect_native_handoff(repeat('a',64),foreign_app,'queer.guide','/go/foreign-native-scope',true,foreign_fp,'https://example.org/foreign-native',NULL) IS NOT NULL THEN RAISE EXCEPTION 'Public native/route capability crossed workspace';END IF;
 IF public.record_redirect_visit(foreign_link,'/go/foreign-native-scope',NULL,NULL,NULL,NULL,NULL,302,NULL,'https://example.org/foreign-native') IS NOT NULL OR public.record_redirect_snapshot_visit(foreign_fp,foreign_link,'/go/foreign-native-scope',NULL,NULL,NULL,NULL,NULL,302,NULL,'https://example.org/foreign-native','{"domain":"queer.guide"}') IS NOT NULL OR public.create_redirect_native_handoff(repeat('e',64),own_app,true,foreign_fp,foreign_link,'/go/foreign-native-scope',NULL,NULL,NULL,NULL,NULL,302,NULL,'https://example.org/foreign-native','{"domain":"queer.guide"}') IS NOT NULL THEN RAISE EXCEPTION 'Public foreign visit/handoff reserved quota';END IF;
 IF public.redirect_password_branding_public(foreign_link) IS NOT NULL THEN RAISE EXCEPTION 'Foreign public branding exposed';END IF;
 BEGIN PERFORM public.reserve_redirect_password_attempt(foreign_link,repeat('f',64));RAISE EXCEPTION 'Foreign password budget spent';EXCEPTION WHEN no_data_found THEN NULL;END;
 golden:=jsonb_populate_record(NULL::public.redirects,'{"id":"00000000-0000-4000-8000-000000000091","workspace_id":"58aa4340-8f21-4b7f-9a10-90be2da89c01","type":"SHORT","slug":"fingerprint-fixture","target":"https://example.org/fingerprint","status_code":302,"is_enabled":true,"is_domain_root":false,"query_mode":"PRESERVE"}');
 IF public.redirect_resolution_fingerprint(golden,'{}',NULL)<>'70c82dc1999535074b0b96e3e266415897b303708d2f923318b09a2473ea5827' THEN RAISE EXCEPTION 'Legacy fingerprint protocol changed';END IF;
 golden.workspace_id:=other;
 IF public.redirect_resolution_fingerprint(golden,'{}',NULL)='70c82dc1999535074b0b96e3e266415897b303708d2f923318b09a2473ea5827' THEN RAISE EXCEPTION 'Workspace move retained a routing fingerprint';END IF;
 result:=public.redirect_resolution_snapshot('queer.guide','own-native-scope');
 own_receipt:=public.create_redirect_native_handoff(repeat('f',64),own_app,true,result->>'fingerprint',own_link,'/go/own-native-scope',NULL,NULL,NULL,NULL,NULL,302,NULL,'https://example.org/own-native','{"domain":"queer.guide"}');
 IF own_receipt->>'clickId' IS NULL OR NOT EXISTS(SELECT FROM public.redirect_native_handoff_receipts WHERE token_hash=repeat('f',64) AND workspace_id=legacy) OR NOT EXISTS(SELECT FROM public.redirect_events WHERE click_id=(own_receipt->>'clickId')::uuid AND workspace_id=legacy) THEN RAISE EXCEPTION 'Public local source lost authoritative receipt/visit workspace';END IF;
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-workspace',legacy,'x-qg-redirect-session-actor',actor)::text,true);
 PERFORM public.reserve_redirect_password_attempt(own_link,repeat('f',64));
 IF (SELECT jsonb_build_object('links',(SELECT jsonb_agg(to_jsonb(r)) FROM public.redirects r WHERE workspace_id=other),'events',(SELECT jsonb_agg(to_jsonb(e) ORDER BY id) FROM public.redirect_events e WHERE workspace_id=other),'apps',(SELECT jsonb_agg(to_jsonb(a)) FROM public.redirect_native_apps a WHERE workspace_id=other),'receipts',(SELECT jsonb_agg(to_jsonb(h) ORDER BY token_hash) FROM public.redirect_native_handoff_receipts h WHERE workspace_id=other),'assets',(SELECT jsonb_agg(to_jsonb(a) ORDER BY id) FROM public.redirect_qr_assets a WHERE workspace_id=other),'brand',(SELECT jsonb_agg(to_jsonb(b)) FROM public.redirect_password_branding b WHERE workspace_id=other),'attempts',(SELECT jsonb_agg(to_jsonb(a)) FROM public.redirect_password_attempts a WHERE workspace_id=other),'images',(SELECT jsonb_agg(to_jsonb(q)) FROM public.redirect_qr_image_links q WHERE workspace_id=other),'imageLog',(SELECT jsonb_agg(to_jsonb(q)) FROM public.redirect_qr_image_creation_log q WHERE workspace_id=other)))<>snapshot THEN RAISE EXCEPTION 'Native/public denial changed foreign state';END IF;
 UPDATE public.redirect_native_handoff_receipts SET created_at=now()-interval '2 days',expires_at=now()-interval '1 day' WHERE token_hash=repeat('f',64);
 -- Internal retention ignores even malformed private selection headers and
 -- remains bounded across active and provisioning workspaces.
 PERFORM set_config('request.headers','{"x-qg-redirect-workspace":"invalid-retention-context"}',true);
 old_count:=public.cleanup_redirect_native_handoffs(1);
 IF old_count<>1 OR (SELECT count(*) FROM public.redirect_native_handoff_receipts WHERE expires_at<=clock_timestamp())<>1 THEN RAISE EXCEPTION 'Global handoff retention ignored its batch bound';END IF;
 old_count:=old_count+public.cleanup_redirect_native_handoffs(1);
 IF old_count<>2 OR EXISTS(SELECT FROM public.redirect_native_handoff_receipts WHERE token_hash=repeat('b',64)) OR NOT EXISTS(SELECT FROM public.redirect_native_handoff_receipts WHERE token_hash=repeat('a',64)) THEN RAISE EXCEPTION 'Global receipt cleanup missed expired history or removed a live receipt';END IF;
 INSERT INTO public.redirect_qr_assets(target_scope,requested_by,mime,bytes,width,height,sha256,state,next_cleanup_at) VALUES('workspace',actor,'image/png',8,1,1,repeat('e',64),'active',now()-interval '1 day') RETURNING id INTO own_asset;
 result:=public.claim_redirect_qr_asset_cleanup();
 IF jsonb_array_length(result)<>1 OR result#>>'{0,id}'<>own_asset::text OR NOT public.finish_redirect_qr_asset_cleanup(own_asset,(result#>>'{0,lease}')::uuid,true) OR public.finish_redirect_qr_asset_cleanup(foreign_orphan_asset,gen_random_uuid(),true) THEN RAISE EXCEPTION 'Asset cleanup claimed an unexpired lease or accepted a forged lease';END IF;
 INSERT INTO public.redirect_qr_image_links(id,token_hash,creator_user_id,principal_key,encoded_url,created_at,expires_at,revoked_at) VALUES(own_image,repeat('d',64),actor,'owner:'||actor,'https://example.org/local-qr',now()-interval '200 days',now()-interval '100 days',now()-interval '100 days');
 result:=public.prune_redirect_qr_image_history();
 IF result->>'images'<>'2' OR result->>'events'<>'2' OR EXISTS(SELECT FROM public.redirect_qr_image_links WHERE id IN(own_image,foreign_image)) THEN RAISE EXCEPTION 'Global QR retention missed expired history';END IF;
 IF NOT public.finish_redirect_qr_asset_cleanup(foreign_orphan_asset,foreign_lease,true) OR (SELECT state FROM public.redirect_qr_assets WHERE id=foreign_asset)<>'active' THEN RAISE EXCEPTION 'Cleanup lost a valid source lease or changed referenced foreign artwork';END IF;
 BEGIN PERFORM public.cleanup_redirect_native_handoffs(0);RAISE EXCEPTION 'Unbounded receipt cleanup accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.claim_redirect_qr_asset_cleanup(6);RAISE EXCEPTION 'Unbounded artwork cleanup accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.prune_redirect_qr_image_history(1001);RAISE EXCEPTION 'Unbounded QR history cleanup accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 FOREACH op IN ARRAY ARRAY['public.cleanup_redirect_native_handoffs(integer)','public.claim_redirect_qr_asset_cleanup(integer)','public.finish_redirect_qr_asset_cleanup(uuid,uuid,boolean)','public.prune_redirect_qr_image_history(integer)'] LOOP
  IF has_function_privilege('authenticated',op,'EXECUTE') OR has_function_privilege('anon',op,'EXECUTE') THEN RAISE EXCEPTION 'Internal retention callable by public roles: %',op;END IF;
 END LOOP;
 IF has_function_privilege('authenticated','public.redirect_public_workspace(text)','EXECUTE') OR has_function_privilege('authenticated','redirect_internal.qr_asset_for_workspace(uuid,uuid)','EXECUTE') THEN RAISE EXCEPTION 'Private public-routing/asset authority leaked';END IF;
END $$;
RESET ROLE;
DO $$ BEGIN
 IF EXISTS(SELECT FROM public.resolve_short_redirect('foreign-native-scope')) OR NOT EXISTS(SELECT FROM public.resolve_short_redirect('own-native-scope')) THEN RAISE EXCEPTION 'Obsolete raw resolver lost its fixed legacy namespace';END IF;
END $$;
ROLLBACK;
